package net.civeira.phylax.feature.observe.observedalert.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRuleReference;

class ObservedAlertFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_alert_filter_builder() {
    ObservedAlertFilter filter = ObservedAlertFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getRule().isPresent(),
        "Rule must be empty if filter is build without it");
    filter.setRule(ObservedAlertRuleReference.of("$ref"));
    Assertions.assertEquals(ObservedAlertRuleReference.of("$ref"), filter.getRule().get(),
        "Rule must be the same as the assigned");
    Assertions.assertFalse(filter.getProblemKey().isPresent(),
        "ProblemKey must be empty if filter is build without it");
    filter.setProblemKey("one");
    Assertions.assertEquals("one", filter.getProblemKey().get(),
        "ProblemKey must be the same as the assigned");
    Assertions.assertFalse(filter.getStatus().isPresent(),
        "Status must be empty if filter is build without it");
    filter.setStatus(null);
    Assertions.assertFalse(filter.getStatus().isPresent(),
        "Status must be the same as the assigned");
    Assertions.assertFalse(filter.getSummary().isPresent(),
        "Summary must be empty if filter is build without it");
    filter.setSummary("one");
    Assertions.assertEquals("one", filter.getSummary().get(),
        "Summary must be the same as the assigned");
  }
}
